#!/usr/bin/env Rscript
# Paired post-minus-pre epithelial transcriptomic analysis for GSE311899.
suppressPackageStartupMessages({library(edgeR); library(data.table); library(jsonlite)})
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop("Usage: 13_test_gse311899_paired_longitudinal.R SOURCE_ROOT WORK_ROOT")
source_root<-normalizePath(args[[1]],winslash="/",mustWork=TRUE);root<-normalizePath(args[[2]],winslash="/",mustWork=TRUE);res<-file.path(root,"results");meta_dir<-file.path(root,"metadata")
counts_path<-file.path(root,"interim","GSE311899_paired_disjoint_epithelial_pseudobulk_counts.tsv.gz");meta_path<-file.path(meta_dir,"GSE311899_paired_disjoint_epithelial_pseudobulk_metadata.tsv");qa_path<-file.path(meta_dir,"GSE311899_paired_disjoint_epithelial_qa.json");program_path<-file.path(source_root,"results","reference_WOI_program_epithelial.tsv");core_path<-file.path(source_root,"results","reference_epithelial_WOI_program_stability_core_cell_specificity.tsv")
out_de<-file.path(res,"GSE311899_paired_disjoint_epithelial_edgeR_QL_all_genes.tsv");out_scores<-file.path(res,"GSE311899_paired_disjoint_epithelial_programme_scores.tsv");out_rec<-file.path(res,"GSE311899_paired_disjoint_epithelial_receptor_paired_effects.tsv");out_prog<-file.path(res,"GSE311899_paired_disjoint_epithelial_programme_paired_effects.tsv");outqa<-file.path(meta_dir,"GSE311899_paired_disjoint_epithelial_analysis_qa.json")
if(any(file.exists(c(out_de,out_scores,out_rec,out_prog,outqa))))stop("Refusing to overwrite P2 test outputs")
preqa<-read_json(qa_path,simplifyVector=TRUE);raw<-fread(counts_path,data.table=FALSE);meta<-fread(meta_path,data.table=FALSE);if(anyDuplicated(raw$gene)||anyDuplicated(meta$pseudobulk_id))stop("Duplicated identifiers")
counts<-as.matrix(raw[,meta$pseudobulk_id,drop=FALSE]);rownames(counts)<-raw$gene;storage.mode(counts)<-"integer";if(any(counts<0L)||any(abs(counts-round(counts))>0))stop("Invalid raw count matrix")
meta$stage<-factor(meta$stage,levels=c("pre","post"));pair_tab<-table(meta$patient_id,meta$stage);if(any(pair_tab!=1L))stop("Each retained patient must have one pre and one post pseudobulk")
patient<-factor(meta$patient_id);design<-model.matrix(~patient+stage,data=meta);if(qr(design)$rank!=ncol(design))stop("Paired design rank deficient")
y<-DGEList(counts=counts);keep<-filterByExpr(y,design);y<-y[keep,,keep.lib.sizes=FALSE];y<-normLibSizes(y);y<-estimateDisp(y,design,robust=TRUE);fit<-glmQLFit(y,design,robust=TRUE);de<-topTags(glmQLFTest(fit,coef="stagepost"),n=Inf,sort.by="none")$table;de$gene<-rownames(de);de<-de[,c("gene",setdiff(names(de),"gene"))]
p<-fread(program_path,data.table=FALSE);core<-fread(core_path,data.table=FALSE);pgenes<-unique(p$gene);cgenes<-unique(core$gene[as.logical(core$epithelial_enriched_2fold_reference_rule)]);mpg<-intersect(pgenes,rownames(counts));mcg<-intersect(cgenes,rownames(counts));if(length(mpg)<ceiling(.8*length(pgenes))||length(mcg)<ceiling(.8*length(cgenes)))stop("Frozen programme mapping below 80%")
ys<-normLibSizes(DGEList(counts=counts));lcp<-cpm(ys,log=TRUE,prior.count=2);scores<-data.frame(meta,frozen_candidate25_score=colMeans(lcp[mpg,,drop=FALSE]),stable_epithelial_core_score=colMeans(lcp[mcg,,drop=FALSE]),ESR1_logCPM=as.numeric(lcp["ESR1",]),PGR_logCPM=as.numeric(lcp["PGR",]))
paired_test<-function(v,tab,seed){wide<-reshape(tab[,c("patient_id","stage",v)],idvar="patient_id",timevar="stage",direction="wide");precol=paste0(v,".pre");postcol=paste0(v,".post");d<-wide[[postcol]]-wide[[precol]];n<-length(d);all_signs<-as.matrix(expand.grid(rep(list(c(-1,1)),n)));nul<-as.vector(all_signs%*%d/n);set.seed(seed);bt<-replicate(20000,mean(sample(d,replace=TRUE)));data.frame(paired_patient_n=n,mean_change_post_minus_pre=mean(d),bootstrap_ci95_low=unname(quantile(bt,.025)),bootstrap_ci95_high=unname(quantile(bt,.975)),exact_signflip_p_two_sided=mean(abs(nul)>=abs(mean(d))-.Machine$double.eps),sign_patterns_enumerated=nrow(all_signs))}
rx<-rbind(cbind(endpoint="ESR1_logCPM",paired_test("ESR1_logCPM",scores,2026091921L)),cbind(endpoint="PGR_logCPM",paired_test("PGR_logCPM",scores,2026091922L)));rx$exact_signflip_BH_q_two_receptors<-p.adjust(rx$exact_signflip_p_two_sided,"BH");rde<-merge(data.frame(gene=c("ESR1","PGR")),de,by="gene",all.x=TRUE,sort=FALSE);rde$endpoint<-paste0(rde$gene,"_logCPM");rde$edgeR_BH_q_two_receptors<-p.adjust(rde$PValue,"BH");rx<-merge(rx,rde,by="endpoint",all.x=TRUE)
px<-rbind(cbind(endpoint="frozen_candidate25_score",frozen_genes=length(pgenes),mapped_genes=length(mpg),paired_test("frozen_candidate25_score",scores,2026091923L)),cbind(endpoint="stable_epithelial_core_score",frozen_genes=length(cgenes),mapped_genes=length(mcg),paired_test("stable_epithelial_core_score",scores,2026091924L)));px$exact_signflip_BH_q_two_scores<-p.adjust(px$exact_signflip_p_two_sided,"BH")
fwrite(de,out_de,sep="\t");fwrite(scores,out_scores,sep="\t");fwrite(rx,out_rec,sep="\t");fwrite(px,out_prog,sep="\t")
qa<-list(analysis_id="IUA_RJ_P2_LONGITUDINAL",inference_unit="paired patient epithelial pseudobulk",paired_patient_n=nrow(pair_tab),comparison="post minus pre within patient",count_model="edgeR v4 QL F-test with patient fixed effects and stage",exact_test="all paired sign flips plus 20,000 paired bootstrap resamples",frozen_programme=list(frozen=length(pgenes),mapped=length(mpg)),stable_core=list(frozen=length(cgenes),mapped=length(mcg)),overlap_status=preqa$overlap_status,nonclaims=c("no treatment efficacy","no causal treatment effect","no clinical endpoint linkage","not independent replication"));write_json(qa,outqa,pretty=TRUE,auto_unbox=TRUE);cat("PASS P2 paired analysis. pairs=",nrow(pair_tab),"\n",sep="")
